//! Property-based tests over code generated by `#[derive(Refine)]`.
//!
//! Each refined type declares a predicate; for values generated in its domain
//! we compare the constructor's verdict (`Ok`/`Err`) against a plain Rust
//! evaluation of the predicate, i.e. the generated runtime check must agree
//! exactly with the semantics of the `requires` clause.
//!
//! Clippy lints tokens embedded in the `#[requires]` attribute itself. The
//! predicate grammar accepts only linear comparisons (e.g. `value >= -10 &&
//! value <= 10`), which `manual_range_contains` rewrites via `.contains()`.
#![allow(clippy::manual_range_contains)]

use proptest::prelude::*;

use tpt_reficon_core::Refine;
use tpt_reficon_macros::Refine as RefineMacro;

/// `0 < value && value <= 100` — runtime-checked (the u8 domain allows 0).
#[derive(RefineMacro)]
#[requires(0 < value && value <= 100)]
pub struct BoundedPercentage(u8);

#[derive(RefineMacro)]
#[requires(value >= -10 && value <= 10)]
pub struct SmallOffset(i16);

#[derive(RefineMacro)]
#[requires(value == 5)] // narrow equality, runtime-checked
pub struct Five(u8);

/// Elided: the u8 domain implies `value <= 255`, so `try_new` never fails.
#[derive(RefineMacro)]
#[requires(value <= 255)]
pub struct Byte(u8);

proptest! {
    #![proptest_config(ProptestConfig { cases: 256, ..ProptestConfig::default() })]

    #[test]
    fn checked_predicates_match_semantics(v in any::<u8>()) {
        let should_hold = 0 < v && v <= 100;
        prop_assert_eq!(
            BoundedPercentage::try_new(v).is_ok(),
            should_hold,
            "predicate mismatch at value {}",
            v
        );
    }

    #[test]
    fn checked_i16_predicates_match_semantics(v in any::<i16>()) {
        let should_hold = (-10..=10).contains(&v);
        prop_assert_eq!(
            SmallOffset::try_new(v).is_ok(),
            should_hold,
            "predicate mismatch at value {}",
            v
        );
    }

    #[test]
    fn narrow_equality_predicate(v in any::<u8>()) {
        prop_assert_eq!(Five::try_new(v).is_ok(), v == 5);
    }

    #[test]
    fn elided_check_always_succeeds(v in any::<u8>()) {
        prop_assert!(Byte::try_new(v).is_ok(), "elided check rejected {v}");
        let b = Byte::new(v); // elided `new` must never panic
        prop_assert_eq!(*b, v);
        prop_assert_eq!(b.into_inner(), v);
    }
}
